INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(0, '360-degree feedback', '/θriː hʌndrəd ˈsɪksti dɪˈɡriː ˈfiːdbæk/', 'noun', '{"zh-TW":["360度反饋"],"en":["performance feedback gathered from multiple sources including peers and subordinates"]}', NULL, 'implement 360-degree feedback / 360-degree feedback process', '[{"en":"The 360-degree feedback revealed blind spots in leadership style.","zh-TW":"360度反饋揭示了領導風格中的盲點。"},{"en":"Employees appreciate 360-degree feedback for its balanced perspective.","zh-TW":"員工欣賞360度反饋的平衡視角。"}]', NULL, NULL, 5, 0, NULL),
(1, 'a la carte', '/ɑː lɑː kɑːrt/', 'phrase', '{"zh-TW":["單點；照菜單點菜"],"en":["ordering individual dishes rather than a set menu"]}', NULL, 'a la carte menu / order a la carte', '[{"en":"We ordered a la carte rather than the set menu.","zh-TW":"我們選擇單點而非套餐。"},{"en":"The a la carte menu offers more variety.","zh-TW":"單點菜單提供更多選擇。"}]', NULL, NULL, 4, 1, NULL),
(2, 'A/B testing', '/ˌeɪ biː ˈtestɪŋ/', 'noun', '{"zh-TW":["A/B測試；對照測試"],"en":["comparing two versions of content to see which performs better"]}', NULL, 'run an A/B test / A/B testing results / implement A/B testing', '[{"en":"A/B testing showed that the red button outperformed the green one.","zh-TW":"A/B測試顯示紅色按鈕的表現優於綠色按鈕。"},{"en":"We use A/B testing to optimize our landing pages.","zh-TW":"我們使用A/B測試優化登陸頁面。"}]', '{"verb":"A/B test"}', NULL, 4, 2, NULL),
(3, 'abandon', '/əˈbændən/', 'verb', '{"zh-TW":["放棄；拋棄","遺棄"],"en":["to give up completely","to leave someone permanently"]}', '{"prefix":{"text":"a-","meaning":"away (離開)"},"root":{"text":"bandon","meaning":"control (控制)"},"logic":"離開控制，意即「放棄」。"}', 'abandon a plan/project/ship', '[{"en":"They had to abandon the project due to lack of funding.","zh-TW":"因資金不足，他們不得不放棄該計畫。"},{"en":"The crew abandoned the sinking ship.","zh-TW":"船員們棄船逃生。"}]', '{"noun":"abandonment","adjective":"abandoned"}', NULL, 3, 3, NULL),
(4, 'abandonment', '/əˈbændənmənt/', 'noun', '{"zh-TW":["放棄；廢棄"],"en":["the act of giving up ownership, a claim, or a contract"]}', NULL, 'project abandonment / abandonment of claim', '[{"en":"The insurance policy covered costs from project abandonment.","zh-TW":"保險單涵蓋了項目放棄的成本。"},{"en":"The lease provided for early abandonment without penalty after five years.","zh-TW":"租約規定五年後可以無罰款提前放棄。"}]', '{"verb":"abandon"}', NULL, 4, 4, NULL),
(5, 'abatement', '/əˈbeɪtmənt/', 'noun', '{"zh-TW":["減少；削減；緩和"],"en":["the action of lessening or removing something, typically pollution or costs"]}', NULL, 'noise abatement / pollution abatement / cost abatement', '[{"en":"The factory installed filters as part of its pollution abatement program.","zh-TW":"工廠安裝了過濾器作為其污染削減計畫的一部分。"},{"en":"Tax abatement can be used to attract businesses to underdeveloped areas.","zh-TW":"稅收減免可用於吸引企業進入欠發達地區。"}]', '{"verb":"abate"}', NULL, 3, 5, NULL),
(6, 'abide', '/əˈbaɪd/', 'verb', '{"zh-TW":["遵守；忍受"],"en":["to accept or obey a rule or decision"]}', '{"prefix":{"text":"a-","meaning":"on (在…上)"},"root":{"text":"bide","meaning":"wait/stay (等待/停留)"},"logic":"停留在規則上，即「遵守」。"}', 'abide by rules/laws/decisions', '[{"en":"All members must abide by the association''s rules.","zh-TW":"所有會員必須遵守協會規則。"},{"en":"We expect partners to abide by the agreement.","zh-TW":"我們期望合作夥伴遵守協議。"}]', NULL, NULL, 2, 6, 628),
(7, 'abide by', '/əˈbaɪd baɪ/', 'verb', '{"zh-TW":["遵守；遵從"],"en":["to accept and act in accordance with a decision or rule"]}', NULL, 'abide by the rules / abide by the contract / abide by the decision', '[{"en":"All parties must abide by the terms of the agreement.","zh-TW":"所有各方必須遵守協議條款。"},{"en":"The company agreed to abide by the regulator''s decision.","zh-TW":"公司同意遵守監管機構的裁決。"}]', NULL, NULL, 3, 7, NULL),
(8, 'ability', '/əˈbɪləti/', 'noun', '{"zh-TW":["能力；才能"],"en":["the power or skill to do something"]}', '{"root":{"text":"abil","meaning":"able (能夠)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"能夠的狀態，即「能力」。"}', 'ability to do sth', '[{"en":"She has the ability to solve complex problems.","zh-TW":"她有解決複雜問題的能力。"},{"en":"Leadership ability is essential for managers.","zh-TW":"領導能力對管理者至關重要。"}]', '{"adjective":"able","adverb":"ably"}', NULL, 3, 8, NULL),
(9, 'able', 'ˈeɪbəl', 'adjective', '{"zh-TW":["能夠；有能力","有才能的"],"en":["having the power to do something","having the skill"]}', NULL, 'able to/be able to', '[{"en":"She is able to handle multiple projects.","zh-TW":"她能夠處理多個專案。"}]', '{"noun":"ability","adverb":"ably"}', NULL, 1, 9, NULL),
(10, 'abolish', '/əˈbɒlɪʃ/', 'verb', '{"zh-TW":["廢除；廢止"],"en":["to officially end a law or system"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使離開成長，即「廢除」。"}', 'abolish a law/system/practice', '[{"en":"The government voted to abolish the outdated regulation.","zh-TW":"政府投票廢除了過時的法規。"},{"en":"Many countries have abolished the death penalty.","zh-TW":"許多國家已廢除死刑。"}]', '{"noun":"abolition"}', NULL, 3, 10, 629),
(11, 'abolition', '/ˌæbəˈlɪʃn/', 'noun', '{"zh-TW":["廢除；廢止"],"en":["the act of officially ending something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"ol","meaning":"grow (成長)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"離開成長的動作，即「廢除」。"}', 'abolition of / call for abolition', '[{"en":"The abolition of trade barriers boosted exports.","zh-TW":"廢除貿易壁壘促進了出口。"},{"en":"Some advocate for the abolition of overtime caps.","zh-TW":"有些人提倡廢除加班上限。"}]', '{"verb":"abolish"}', NULL, 3, 11, NULL),
(12, 'about', '/əˈbaʊt/', 'preposition', '{"zh-TW":["關於；大約"],"en":["concerning","approximately","concerning; approximately"]}', NULL, 'think about / about to; about + 名詞/V-ing', '[{"en":"What is this meeting about?","zh-TW":"這個會議是關於什麼的？"},{"en":"There are about 200 employees.","zh-TW":"大約有200名員工。"},{"en":"The book is about history.","zh-TW":"這本書是關於歷史的。"},{"en":"There are about 50 people here.","zh-TW":"這裡大約有50個人。"}]', '{"preposition":"about","adverb":"about"}', NULL, 2, 12, NULL),
(13, 'above', '/əˈbʌv/', 'preposition', '{"zh-TW":["在…上方；超過","在…上面；超過","在...上方；超過"],"en":["higher than","more than","in or to a higher position","at a higher level than; more than"]}', NULL, 'above all / above average; above all (最重要的是)', '[{"en":"Sales rose above expectations.","zh-TW":"銷售額超出了預期。"},{"en":"Above all, safety comes first.","zh-TW":"最重要的是，安全第一。"},{"en":"The temperature rose above 30 degrees.","zh-TW":"溫度升到了30度以上。"},{"en":"Above all, be honest.","zh-TW":"最重要的是，要誠實。"},{"en":"The plane flew above the clouds.","zh-TW":"飛機在雲層上方飛行。"},{"en":"Temperatures rose above 30 degrees.","zh-TW":"氣溫升超過30度。"}]', '{"preposition":"above","adjective":"above-mentioned"}', NULL, 2, 13, NULL),
(14, 'above the line', '/əˈbʌv ðə laɪn/', 'phrase', '{"zh-TW":["線上項目；主要項目"],"en":["relating to revenue or costs directly involved in a company''s core operations"]}', NULL, 'above-the-line costs / above-the-line promotions', '[{"en":"Above-the-line advertising includes TV, radio, and national press campaigns.","zh-TW":"線上廣告包括電視、廣播和全國性報紙活動。"},{"en":"Above-the-line items in the income statement reflect core operational performance.","zh-TW":"損益表中的線上項目反映了核心運營績效。"}]', '{"opposite":"below the line"}', NULL, 5, 14, NULL),
(15, 'above-mentioned', '/əˌbʌv ˈmenʃənd/', 'adjective', '{"zh-TW":["上述的；上文所提到的"],"en":["previously mentioned in the same document"]}', NULL, 'the above-mentioned conditions / above-mentioned parties', '[{"en":"The above-mentioned requirements apply to all applicants.","zh-TW":"上述要求適用於所有申請者。"},{"en":"The above-mentioned vendors have been approved.","zh-TW":"上述供應商已獲批准。"}]', NULL, NULL, 5, 15, NULL),
(16, 'above-the-line', '/əˌbʌv ðə laɪn/', 'adjective', '{"zh-TW":["線上的；媒體廣告的"],"en":["relating to advertising that uses mass media channels to reach a wide audience"]}', NULL, 'above-the-line advertising / above-the-line promotion', '[{"en":"TV and radio are classic above-the-line advertising channels.","zh-TW":"電視和廣播是傳統的線上廣告渠道。"},{"en":"The campaign combined above-the-line and digital media.","zh-TW":"該活動結合了線上廣告和數位媒體。"}]', '{"opposite":"below-the-line"}', NULL, 5, 16, NULL),
(17, 'abrupt', '/əˈbrʌpt/', 'adjective', '{"zh-TW":["突然的；意外的"],"en":["happening suddenly or without warning"]}', NULL, 'abrupt change / abrupt departure / abrupt decision', '[{"en":"The abrupt resignation of the CEO shocked investors.","zh-TW":"執行長的突然辭職震驚了投資者。"},{"en":"An abrupt halt in production disrupted the supply chain.","zh-TW":"生產的突然停止打亂了供應鏈。"}]', '{"adverb":"abruptly","noun":"abruptness"}', NULL, 2, 17, 967),
(18, 'abscond', '/əbˈskɒnd/', 'verb', '{"zh-TW":["潛逃；逃匿"],"en":["to leave hurriedly and secretly, typically to escape from custody"]}', NULL, 'abscond with funds / abscond from justice / abscond overseas', '[{"en":"The suspect absconded before the arrest warrant could be served.","zh-TW":"嫌疑人在逮捕令送達前潛逃了。"},{"en":"The accountant absconded with client funds and fled to another country.","zh-TW":"這位會計師攜客戶資金潛逃至另一個國家。"}]', '{"noun":"absconsion"}', NULL, 3, 18, NULL),
(19, 'absence', '/ˈæbsəns/', 'noun', '{"zh-TW":["缺席；不在","缺乏"],"en":["the state of being away","the lack of something"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sens","meaning":"be (存在)"},"logic":"離開存在的狀態，即「缺席」。"}', 'in the absence of / leave of absence', '[{"en":"In the absence of the manager, the assistant took charge.","zh-TW":"經理不在時，助理負責管理。"},{"en":"She took a leave of absence for personal reasons.","zh-TW":"她因私人原因請假。"}]', '{"adjective":"absent"}', NULL, 3, 19, 968),
(20, 'absenteeism', 'ˌæbsənˈtiːɪzəm', 'noun', '{"zh-TW":["缺勤；曠職","曠工"],"en":["frequent absence from work","being away without permission"]}', NULL, 'reduce absenteeism/absenteeism rate', '[{"en":"We aim to reduce absenteeism.","zh-TW":"我們致力於減少缺勤。"}]', '{"adjective":"absent"}', NULL, 4, 20, 738),
(21, 'absorb', '/əbˈzɔːrb/', 'verb', '{"zh-TW":["吸收","全神貫注"],"en":["to take in or soak up","to occupy attention fully"]}', '{"prefix":{"text":"ab-","meaning":"away (離開)"},"root":{"text":"sorb","meaning":"suck (吸)"},"logic":"把東西吸走，即「吸收」。"}', 'absorb information/costs; absorb information / absorb moisture', '[{"en":"The company will absorb the extra shipping costs.","zh-TW":"公司將承擔額外的運費。"},{"en":"She was completely absorbed in her research.","zh-TW":"她完全沉浸在研究中。"},{"en":"Plants absorb carbon dioxide from the air.","zh-TW":"植物從空氣中吸收二氧化碳。"},{"en":"She quickly absorbed all the new information.","zh-TW":"她很快吸收了所有新資訊。"}]', '{"noun":"absorption","adjective":"absorbing"}', NULL, 2, 21, NULL),
(22, 'absorption', '/əbˈzɔːrpʃən/', 'noun', '{"zh-TW":["吸收；融合"],"en":["the process of absorbing or being absorbed"]}', NULL, 'economic absorption / absorption of migrants / sound absorption', '[{"en":"The absorption of new technology often transforms entire industries.","zh-TW":"新技術的吸收往往改變整個行業。"},{"en":"The economy showed strong absorption of new workers after the recession.","zh-TW":"衰退後，經濟顯示出對新工人的強大吸收能力。"}]', '{"verb":"absorb","adjective":"absorbed"}', NULL, 4, 22, NULL),
(23, 'absorption costing', '/əbˈzɔːrpʃən ˈkɒstɪŋ/', 'noun', '{"zh-TW":["完全成本法；吸收成本法"],"en":["a method of costing that includes all manufacturing costs in product cost"]}', NULL, 'apply absorption costing / absorption costing method', '[{"en":"Under absorption costing, fixed overhead is included in product cost.","zh-TW":"在完全成本法下，固定費用計入產品成本。"},{"en":"Absorption costing can distort profit when inventory levels change.","zh-TW":"當庫存水準變化時，完全成本法可能扭曲利潤。"}]', NULL, NULL, 5, 23, NULL),
(24, 'abstract', '/ˈæbstrækt/', 'adjective', '{"zh-TW":["抽象的","摘要"],"en":["existing in thought but not physical","a summary of a document","existing in thought rather than having a physical existence"]}', '{"prefix":{"text":"abs-","meaning":"away (離開)"},"root":{"text":"tract","meaning":"draw (拉)"},"logic":"從具體中拉出來，即「抽象的」。"}', 'abstract concept/idea/art; abstract art / abstract concept', '[{"en":"The report includes an abstract summarizing key findings.","zh-TW":"報告包含一份摘要，概述了主要發現。"},{"en":"Abstract thinking is required for strategic planning.","zh-TW":"策略規劃需要抽象思維。"},{"en":"The painting is very abstract.","zh-TW":"這幅畫非常抽象。"},{"en":"Justice is an abstract concept.","zh-TW":"正義是一個抽象概念。"}]', '{"noun":"abstraction","adverb":"abstractly","verb":"abstract"}', NULL, 3, 24, 969),
(25, 'abstract reasoning', '/''æbstrækt ˌriːzənɪŋ/', 'noun', '{"zh-TW":["抽象推理"],"en":["the ability to understand and think about concepts and ideas that are not concrete or tangible"]}', NULL, 'develop abstract reasoning / strong abstract reasoning / test abstract reasoning', '[{"en":"Abstract reasoning is tested in many aptitude exams used in hiring processes.","zh-TW":"抽象推理在許多用於招聘流程的資質考試中被測試。"},{"en":"Solving mathematical puzzles can help develop abstract reasoning skills.","zh-TW":"解決數學謎題有助於培養抽象推理能力。"}]', '{"adjective":"abstract"}', NULL, 5, 25, NULL),
(26, 'abstraction', '/æbˈstrækʃən/', 'noun', '{"zh-TW":["抽象；抽象概念"],"en":["the quality of dealing with ideas rather than events"]}', NULL, 'high level of abstraction / conceptual abstraction / layer of abstraction', '[{"en":"The model works at a high level of abstraction.","zh-TW":"該模型在高度抽象的層次上運作。"},{"en":"Mathematics involves reasoning through abstraction.","zh-TW":"數學涉及通過抽象進行推理。"}]', '{"adjective":"abstract","verb":"abstract"}', NULL, 4, 26, NULL),
(27, 'abstraction layer', '/æbˈstrækʃən ˈleɪər/', 'noun', '{"zh-TW":["抽象層"],"en":["a level of programming that hides implementation details from the user"]}', NULL, 'add abstraction layer / software abstraction layer / network abstraction layer', '[{"en":"An abstraction layer allows developers to work without knowing underlying details.","zh-TW":"抽象層允許開發者在不了解底層細節的情況下工作。"},{"en":"Operating systems provide an abstraction layer between hardware and software.","zh-TW":"作業系統在硬體和軟體之間提供抽象層。"}]', NULL, NULL, 5, 27, NULL),
(28, 'abstraction level', '/æbˈstrækʃən ˈlevəl/', 'noun', '{"zh-TW":["抽象層級"],"en":["a degree of complexity at which a system is described or modeled"]}', NULL, 'higher abstraction level / lower abstraction level / appropriate abstraction level', '[{"en":"Working at the right abstraction level improves code readability.","zh-TW":"在正確的抽象層級工作提高了代碼可讀性。"},{"en":"The system architecture defines multiple abstraction levels for different concerns.","zh-TW":"系統架構為不同的關注點定義了多個抽象層級。"}]', NULL, NULL, 5, 28, NULL),
(29, 'abstruse', '/æbˈstruːs/', 'adjective', '{"zh-TW":["深奧的；難以理解的"],"en":["difficult to understand; obscure"]}', NULL, 'abstruse theory / abstruse concept / abstruse language', '[{"en":"The professor''s abstruse lecture confused most students.","zh-TW":"教授深奧的講課讓大多數學生感到困惑。"},{"en":"The legal text was written in abstruse terminology.","zh-TW":"該法律文本以晦澀的術語撰寫。"}]', '{"adverb":"abstrusely"}', NULL, 3, 29, NULL),
(30, 'abundant', '/əˈbʌndənt/', 'adjective', '{"zh-TW":["豐富的；大量的"],"en":["existing in large quantities; more than enough"]}', '{"prefix":{"text":"ab-","meaning":"over (超出)"},"root":{"text":"und","meaning":"wave (波浪)"},"suffix":{"text":"-ant","meaning":"having quality (具有特質)"},"logic":"如波浪般溢出，即「豐富的」。"}', 'abundant resources/supply/evidence', '[{"en":"The region has abundant natural resources.","zh-TW":"該地區擁有豐富的自然資源。"},{"en":"There is abundant evidence to support the claim.","zh-TW":"有大量證據支持這個說法。"}]', '{"noun":"abundance","adverb":"abundantly"}', NULL, 3, 30, NULL),
(31, 'academia', '/ˌækəˈdiːmiə/', 'noun', '{"zh-TW":["學術界"],"en":["the world of universities and scholarly research"]}', NULL, 'in academia / bridge between academia and industry', '[{"en":"She spent 10 years in academia before joining the firm.","zh-TW":"她在加入公司前在學術界待了10年。"},{"en":"We bridge the gap between academia and industry.","zh-TW":"我們搭建學術界與產業界之間的橋樑。"}]', '{"noun":"academia","adjective":"academic","adverb":"academically"}', NULL, 3, 31, NULL),
(32, 'academic', '/ˌækəˈdɛmɪk/', 'adjective', '{"zh-TW":["學術的"],"en":["relating to education and studying"]}', NULL, 'academic year / academic achievement', '[{"en":"Her academic performance is excellent.","zh-TW":"她的學業成績很優秀。"},{"en":"The academic year starts in September.","zh-TW":"學年從九月開始。"}]', '{"noun":"academia","noun2":"academy"}', NULL, 3, 32, NULL),
(33, 'academic advisor', '/''ækəˌdemɪk ədˌvaɪzər/', 'noun', '{"zh-TW":["學業輔導員；課業顧問"],"en":["a faculty member or staff who guides students in planning their academic program"]}', NULL, 'meet with an academic advisor / consult an academic advisor / academic advisor recommendation', '[{"en":"She met with her academic advisor to plan her course schedule for the semester.","zh-TW":"她與學業輔導員會面，規劃學期的課程安排。"},{"en":"Academic advisors help students navigate degree requirements and career planning.","zh-TW":"學業輔導員幫助學生了解學位要求和職業規劃。"}]', NULL, NULL, 5, 33, NULL),
(34, 'academic calendar', '/''ækəˌdemɪk ˌkæləndər/', 'noun', '{"zh-TW":["學年曆；學術日曆"],"en":["a schedule of the academic year including key dates for terms, exams, and vacations"]}', NULL, 'consult the academic calendar / academic calendar dates / follow the academic calendar', '[{"en":"Students should consult the academic calendar to plan their study schedules.","zh-TW":"學生應查閱學年曆，制定學習計劃。"},{"en":"The academic calendar shows that the final exams begin on December eighteenth.","zh-TW":"學年曆顯示期末考試從十二月十八日開始。"}]', NULL, NULL, 5, 34, NULL),
(35, 'academic excellence', '/''ækəˌdemɪk ˌeksələns/', 'noun', '{"zh-TW":["學術卓越；學業優秀"],"en":["consistently high standards of achievement in academic work"]}', NULL, 'pursue academic excellence / reward academic excellence / achieve academic excellence', '[{"en":"The award recognizes students who have demonstrated academic excellence throughout the year.","zh-TW":"該獎項表彰在整個學年中展示出學術卓越的學生。"},{"en":"Achieving academic excellence requires both discipline and a genuine love of learning.","zh-TW":"實現學術卓越需要紀律和對學習的真誠熱愛。"}]', NULL, NULL, 5, 35, NULL),
(36, 'academic integrity', '/''ækəˌdemɪk ɪnˈteɡrɪti/', 'noun', '{"zh-TW":["學術誠信"],"en":["the commitment to honesty, fairness, and ethical behavior in academic work"]}', NULL, 'uphold academic integrity / academic integrity policy / violate academic integrity', '[{"en":"All students must sign an academic integrity pledge at the start of each semester.","zh-TW":"所有學生必須在每學期開始時簽署學術誠信承諾書。"},{"en":"The university takes academic integrity violations very seriously.","zh-TW":"大學非常重視學術誠信違規行為。"}]', NULL, NULL, 5, 36, NULL),
(37, 'academic journal', '/''ækəˌdemɪk ˌdʒɜːrnəl/', 'noun', '{"zh-TW":["學術期刊"],"en":["a peer-reviewed periodical in which scholarship relating to a particular academic discipline is published"]}', NULL, 'publish in an academic journal / subscribe to an academic journal / academic journal article', '[{"en":"Her research was published in a leading academic journal in her field.","zh-TW":"她的研究發表在她領域的頂尖學術期刊上。"},{"en":"Students are encouraged to read academic journals to stay current with research.","zh-TW":"鼓勵學生閱讀學術期刊，以了解最新研究。"}]', NULL, NULL, 5, 37, NULL),
(38, 'academic misconduct', '/''ækəˌdemɪk ˌmɪsˈkɒndʌkt/', 'noun', '{"zh-TW":["學術不端行為；學術違規"],"en":["any action that violates the established academic standards of integrity and fairness"]}', NULL, 'commit academic misconduct / penalize academic misconduct / report academic misconduct', '[{"en":"Cheating on an exam is a serious form of academic misconduct.","zh-TW":"在考試中作弊是一種嚴重的學術不端行為。"},{"en":"The university committee reviewed the case of academic misconduct and issued a warning.","zh-TW":"大學委員會審查了學術不端行為案例並發出了警告。"}]', NULL, NULL, 5, 38, NULL),
(39, 'academic performance', '/''ækəˌdemɪk pəˈfɔːrməns/', 'noun', '{"zh-TW":["學業成績；學術表現"],"en":["the extent to which a student has achieved their educational goals"]}', NULL, 'improve academic performance / measure academic performance / decline in academic performance', '[{"en":"Her academic performance improved significantly after she joined a study group.","zh-TW":"她加入學習小組後，學業成績顯著提高。"},{"en":"Schools monitor academic performance to identify students who need additional support.","zh-TW":"學校監測學業成績，以識別需要額外支持的學生。"}]', NULL, NULL, 5, 39, NULL),
(40, 'academic writing', '/''ækəˌdemɪk ˌraɪtɪŋ/', 'noun', '{"zh-TW":["學術寫作"],"en":["a formal style of writing used in universities and scholarly publications"]}', NULL, 'improve academic writing / academic writing style / academic writing course', '[{"en":"She took a course in academic writing to improve her essay technique.","zh-TW":"她選修了一門學術寫作課程，以提高她的論文寫作技巧。"},{"en":"Academic writing requires a formal tone, precise language, and proper citations.","zh-TW":"學術寫作需要正式的語氣、精確的語言和適當的引用。"}]', NULL, NULL, 5, 40, NULL),
(41, 'academic year', '/ˌækəˈdɛmɪk jɪər/', 'noun', '{"zh-TW":["學年"],"en":["the annual period during which students attend school or college"]}', NULL, 'start of the academic year / academic year calendar', '[{"en":"The academic year begins in September and ends in June.","zh-TW":"學年從9月開始，6月結束。"},{"en":"Registration opens two months before the academic year begins.","zh-TW":"入學申請在學年開始前兩個月開放。"}]', NULL, NULL, 5, 41, NULL),
(42, 'accelerate', '/əkˈseləreɪt/', 'verb', '{"zh-TW":["加速；促進"],"en":["to increase in speed","to cause to happen sooner"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"celer","meaning":"speed (速度)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使朝向速度，即「加速」。"}', 'accelerate growth/development', '[{"en":"The company aims to accelerate its expansion into Asian markets.","zh-TW":"公司旨在加速擴展亞洲市場。"},{"en":"Technology has accelerated the pace of change.","zh-TW":"科技加速了變革的步伐。"}]', '{"noun":"acceleration"}', NULL, 4, 42, 632),
(43, 'accelerated depreciation', '/əkˌseləreɪtɪd dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["加速折舊"],"en":["a depreciation method that records higher expenses in early years of an asset''s life"]}', NULL, 'apply accelerated depreciation / accelerated depreciation schedule', '[{"en":"Accelerated depreciation reduces taxable income in the early years of an asset.","zh-TW":"加速折舊在資產的前幾年降低了應稅收入。"},{"en":"The tax authorities allow accelerated depreciation for certain qualifying assets.","zh-TW":"稅務機關允許對某些符合條件的資產使用加速折舊。"}]', NULL, NULL, 5, 43, NULL),
(44, 'accept', '/əkˈsept/', 'verb', '{"zh-TW":["接受；認可"],"en":["to agree to receive something","to believe something to be true","to agree to receive; to believe something is true"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cept","meaning":"take (拿取)"},"logic":"朝向自己拿取，即「接受」。"}', 'accept an offer/invitation; accept an offer/invitation/responsibility', '[{"en":"She accepted the job offer without hesitation.","zh-TW":"她毫不猶豫地接受了工作邀約。"},{"en":"The board accepted the proposal unanimously.","zh-TW":"董事會一致通過了該提案。"},{"en":"She accepted the job offer.","zh-TW":"她接受了這份工作。"},{"en":"He refused to accept the blame.","zh-TW":"他拒絕接受指責。"}]', '{"noun":"acceptance","adjective":"acceptable"}', NULL, 2, 44, NULL),
(45, 'acceptable', 'əkˈsɛptəbəl', 'adjective', '{"zh-TW":["可接受的；滿意的","還不錯的"],"en":["satisfactory","good enough"]}', NULL, 'acceptable quality/acceptable behavior', '[{"en":"This is an acceptable solution.","zh-TW":"這是一個可接受的解決方案。"}]', '{"noun":"acceptability","adverb":"acceptably"}', NULL, 4, 45, NULL),
(46, 'acceptance', '/ækˈsɛptəns/', 'noun', '{"zh-TW":["接受；承諾"],"en":["agreement to receive or undertake something offered"]}', NULL, 'acceptance of terms / written acceptance', '[{"en":"Please confirm your acceptance of the offer in writing.","zh-TW":"請以書面形式確認您接受此報價。"},{"en":"Acceptance of the contract terms is required before work begins.","zh-TW":"在工作開始之前需要接受合約條款。"}]', '{"verb":"accept","adjective":"accepted"}', NULL, 4, 46, NULL),
(47, 'acceptance testing', '/əkˈseptəns ˈtestɪŋ/', 'noun', '{"zh-TW":["驗收測試"],"en":["testing conducted to verify that a system meets specified requirements before final acceptance"]}', NULL, 'conduct acceptance testing / acceptance testing criteria', '[{"en":"The client conducted acceptance testing before signing off on the software.","zh-TW":"客戶在驗收軟件之前進行了驗收測試。"},{"en":"Acceptance testing ensures the delivered system matches agreed specifications.","zh-TW":"驗收測試確保交付的系統符合商定規格。"}]', NULL, NULL, 5, 47, NULL),
(48, 'access', '/ˈækses/', 'noun', '{"zh-TW":["進入；使用權","存取"],"en":["the opportunity to approach or enter","the right to use something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cess","meaning":"go (走)"},"logic":"走向某處，即「進入、存取」。"}', 'access to information/system', '[{"en":"Employees have access to the company database.","zh-TW":"員工可以存取公司資料庫。"},{"en":"The building provides wheelchair access.","zh-TW":"該建築提供輪椅通道。"}]', '{"adjective":"accessible","noun":"accessibility"}', NULL, 2, 48, 245),
(49, 'access control', '/ˈækses kənˈtrəʊl/', 'noun', '{"zh-TW":["存取控制"],"en":["mechanisms that restrict access to resources based on identity and permissions"]}', NULL, 'implement access control / access control list / role-based access control', '[{"en":"Role-based access control assigns permissions based on user roles.","zh-TW":"基於角色的存取控制根據用戶角色分配權限。"},{"en":"Access control logs help audit who accessed sensitive information.","zh-TW":"存取控制日誌幫助審計誰訪問了敏感信息。"}]', NULL, NULL, 5, 49, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(50, 'accession', '/ækˈseʃən/', 'noun', '{"zh-TW":["加入；就任"],"en":["formal joining of a group or treaty; coming to a position of power"]}', NULL, 'accession to a treaty / accession to the EU / accession negotiations', '[{"en":"The country''s accession to the trade agreement took three years of negotiations.","zh-TW":"該國加入貿易協議歷時三年的談判。"},{"en":"Presidential accession must follow established constitutional procedures.","zh-TW":"總統就任必須遵循既定的憲法程序。"}]', '{"verb":"accede"}', NULL, 3, 50, NULL),
(51, 'accident', 'ˈæksɪdənt', 'noun', '{"zh-TW":["意外；事故","偶然"],"en":["an unpleasant event that was not planned","a chance event"]}', NULL, 'car accident/work accident', '[{"en":"There was an accident on the highway.","zh-TW":"高速公路上發生了事故。"}]', '{"adjective":"accidental","adverb":"accidentally"}', NULL, 3, 51, NULL),
(52, 'accident report', '/ˈæksɪdənt rɪˈpɔːrt/', 'noun', '{"zh-TW":["事故報告"],"en":["a written account of a workplace accident"]}', NULL, 'file an accident report / complete an accident report', '[{"en":"An accident report must be submitted within 24 hours.","zh-TW":"事故報告必須在24小時內提交。"},{"en":"The accident report described how the injury occurred.","zh-TW":"事故報告描述了受傷是如何發生的。"}]', NULL, NULL, 5, 52, NULL),
(53, 'accommodate', '/əˈkɒmədeɪt/', 'verb', '{"zh-TW":["容納；適應","提供住宿"],"en":["to provide lodging or room for","to adjust to fit needs"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"commod","meaning":"fit (適合)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使適合，即「容納、適應」。"}', 'accommodate guests/needs/requests', '[{"en":"The hotel can accommodate up to 500 guests.","zh-TW":"該飯店可容納最多500位客人。"},{"en":"We will try to accommodate your schedule.","zh-TW":"我們會盡量配合您的時間表。"}]', '{"noun":"accommodation"}', NULL, 4, 53, 1),
(54, 'accommodation', '/əˌkɒməˈdeɪʃən/', 'noun', '{"zh-TW":["住宿設施"],"en":["a place to stay, especially on a trip"]}', NULL, 'hotel accommodation / book accommodation', '[{"en":"The accommodation was clean and comfortable.","zh-TW":"住宿環境乾淨舒適。"},{"en":"We need to arrange accommodation for conference delegates.","zh-TW":"我們需要為與會代表安排住宿。"}]', '{"verb":"accommodate","adjective":"accommodating"}', NULL, 5, 54, NULL),
(55, 'accomplish', '/əˈkɒmplɪʃ/', 'verb', '{"zh-TW":["完成；達成"],"en":["to succeed in doing or completing something","to achieve or complete successfully"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"compli","meaning":"fill (填滿)"},"suffix":{"text":"-ish","meaning":"to make (使)"},"logic":"使填滿完成，即「完成」。"}', 'accomplish a goal/task/mission; accomplish a goal / accomplish a task', '[{"en":"She accomplished all her objectives ahead of schedule.","zh-TW":"她提前完成了所有目標。"},{"en":"What do you hope to accomplish this quarter?","zh-TW":"你希望這季度達成什麼？"},{"en":"She accomplished her goal of running a marathon.","zh-TW":"她達成了跑馬拉松的目標。"},{"en":"What do you hope to accomplish today?","zh-TW":"你今天希望完成什麼？"}]', '{"noun":"accomplishment"}', NULL, 4, 55, 634),
(56, 'accomplishment', 'əˈkɒmplɪʃmənt', 'noun', '{"zh-TW":["成就；完成","業績"],"en":["something achieved successfully","a skill or ability"]}', NULL, 'list accomplishments/key accomplishment', '[{"en":"Please list your key accomplishments.","zh-TW":"請列出您的主要成就。"}]', '{"verb":"accomplish","adjective":"accomplished"}', NULL, 5, 56, NULL),
(57, 'account', '/əˈkaʊnt/', 'noun', '{"zh-TW":["帳戶；帳目","描述；報告"],"en":["a record of money received and spent","a description of an event"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"count","meaning":"count (計算)"},"logic":"朝向計算，即「帳戶」。"}', 'bank account / on account of', '[{"en":"Please transfer the payment to our company account.","zh-TW":"請將款項匯入我們的公司帳戶。"},{"en":"She gave a detailed account of the incident.","zh-TW":"她詳細描述了該事件。"}]', '{"noun":"accountant","adjective":"accountable"}', NULL, 3, 57, 246),
(58, 'account holder', '/əˈkaʊnt ˈhəʊldər/', 'noun', '{"zh-TW":["帳戶持有人"],"en":["the person or entity who owns a bank account"]}', NULL, 'primary account holder / joint account holder', '[{"en":"The account holder must sign all withdrawal forms.","zh-TW":"帳戶持有人必須在所有提款單上簽名。"},{"en":"She is the primary account holder on the joint account.","zh-TW":"她是聯名帳戶的主要帳戶持有人。"}]', NULL, NULL, 5, 58, NULL),
(59, 'account management', '/əˈkaʊnt ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["客戶管理；帳戶管理"],"en":["managing ongoing relationships with existing clients to retain and grow business"]}', NULL, 'strategic account management / key account management / account management team', '[{"en":"Strong account management is key to customer retention.","zh-TW":"強大的客戶管理是客戶保留的關鍵。"},{"en":"The account management team meets clients quarterly to review performance.","zh-TW":"帳戶管理團隊每季與客戶會面以審查績效。"}]', '{"noun":"account manager"}', NULL, 5, 59, NULL),
(60, 'account payable', '/əˈkaʊnt ˈpeɪəbl/', 'noun', '{"zh-TW":["應付帳款"],"en":["money owed by a company to suppliers for goods and services received"]}', NULL, 'pay the account payable / outstanding account payable', '[{"en":"The account payable was due within 30 days of the invoice date.","zh-TW":"應付帳款在發票日期後30天到期。"},{"en":"Managing account payable terms improves working capital efficiency.","zh-TW":"管理應付帳款條款提高了營運資金效率。"}]', '{"plural":"accounts payable"}', NULL, 5, 60, NULL),
(61, 'account receivable financing', '/əˈkaʊnt rɪˈsiːvəbl ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["應收帳款融資"],"en":["using outstanding invoices as collateral to obtain funding"]}', NULL, 'use account receivable financing / AR financing facility', '[{"en":"Account receivable financing helped the firm bridge its cash gap.","zh-TW":"應收帳款融資幫助公司彌補了現金缺口。"},{"en":"Banks offer account receivable financing to businesses with slow-paying clients.","zh-TW":"銀行為有緩慢付款客戶的企業提供應收帳款融資。"}]', NULL, NULL, 5, 61, NULL),
(62, 'accountability', '/əˌkaʊntəˈbɪlɪti/', 'noun', '{"zh-TW":["責任；問責"],"en":["the obligation to accept responsibility for one''s actions"]}', NULL, 'corporate accountability / accountability framework', '[{"en":"Accountability is central to good corporate governance.","zh-TW":"問責制是良好公司治理的核心。"},{"en":"The CEO was held to strict accountability for the losses.","zh-TW":"首席執行官對虧損負有嚴格責任。"}]', '{"adjective":"accountable","verb":"account"}', NULL, 5, 62, 739),
(63, 'accountability framework', '/''əˌkaʊntəˌbɪlɪti ˌfreɪmwɜːrk/', 'noun', '{"zh-TW":["問責框架；責任架構"],"en":["a structured system of responsibilities and expectations to ensure people are answerable for their actions"]}', NULL, 'establish an accountability framework / accountability framework requirements / implement an accountability framework', '[{"en":"The new accountability framework assigns clear responsibilities to each department.","zh-TW":"新的問責框架為每個部門分配了明確的責任。"},{"en":"Organizations without an accountability framework often struggle to address failures effectively.","zh-TW":"沒有問責框架的組織通常難以有效地解決失敗問題。"}]', NULL, NULL, 5, 63, NULL),
(64, 'accountant', '/əˈkaʊntənt/', 'noun', '{"zh-TW":["會計師；會計人員"],"en":["a professional who maintains and audits financial records"]}', NULL, 'qualified accountant / hire an accountant / management accountant', '[{"en":"The accountant prepared the year-end financial statements.","zh-TW":"會計師準備了年末財務報表。"},{"en":"A certified accountant is required for statutory audits.","zh-TW":"法定審計需要認證會計師。"}]', '{"plural":"accountants","adjective":"accounting"}', NULL, 4, 64, NULL),
(65, 'accounts payable', '/əˈkaʊnts ˈpeɪəbl/', 'noun', '{"zh-TW":["應付帳款"],"en":["money a company owes to its suppliers or vendors"]}', NULL, 'accounts payable process / manage accounts payable', '[{"en":"Extending accounts payable terms preserved cash.","zh-TW":"延長應付帳款期限保留了現金。"},{"en":"The accounts payable department processes invoices weekly.","zh-TW":"應付帳款部門每週處理發票。"}]', '{"abbreviation":"AP"}', NULL, 5, 65, NULL),
(66, 'accounts receivable', '/əˈkaʊnts rɪˈsiːvəbl/', 'noun', '{"zh-TW":["應收帳款"],"en":["money owed to a company by its customers"]}', NULL, 'manage accounts receivable / accounts receivable turnover', '[{"en":"High accounts receivable can signal collection problems.","zh-TW":"高應收帳款可能表明收款問題。"},{"en":"They factored their accounts receivable to improve cash flow.","zh-TW":"他們將應收帳款進行保理以改善現金流。"}]', '{"abbreviation":"AR"}', NULL, 5, 66, NULL),
(67, 'accounts receivable turnover', '/əˈkaʊnts rɪˈsiːvəbl ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["應收帳款周轉率"],"en":["a measure of how efficiently a company collects its outstanding receivables"]}', NULL, 'improve accounts receivable turnover / calculate accounts receivable turnover', '[{"en":"A high accounts receivable turnover indicates efficient credit management.","zh-TW":"高應收帳款周轉率表明信用管理效率高。"},{"en":"The company improved its accounts receivable turnover by tightening credit terms.","zh-TW":"公司通過收緊信用條款改善了應收帳款周轉率。"}]', NULL, NULL, 5, 67, NULL),
(68, 'accounts reconciliation', '/əˈkaʊnts ˌrekənsɪliˈeɪʃən/', 'noun', '{"zh-TW":["帳戶對帳"],"en":["matching transactions between accounting records and bank statements"]}', NULL, 'perform accounts reconciliation / monthly accounts reconciliation', '[{"en":"Accounts reconciliation revealed an unrecorded transaction.","zh-TW":"帳戶對帳發現了一筆未記錄的交易。"},{"en":"IT tools have automated the accounts reconciliation process.","zh-TW":"IT工具已自動化了帳戶對帳流程。"}]', NULL, NULL, 5, 68, NULL),
(69, 'accreditation', '/əˌkrɛdɪˈteɪʃən/', 'noun', '{"zh-TW":["認可；認證"],"en":["official recognition that a program meets established standards"]}', NULL, 'accreditation process / seek accreditation', '[{"en":"The university received accreditation from the national board.","zh-TW":"這所大學獲得了國家委員會的認可。"},{"en":"Accreditation ensures that educational programs meet quality standards.","zh-TW":"認證確保教育計劃符合品質標準。"}]', '{"verb":"accredit","adjective":"accredited"}', NULL, 5, 69, 740),
(70, 'accreditation body', '/əˌkrɛdɪˈteɪʃən ˈbɒdi/', 'noun', '{"zh-TW":["認證機構"],"en":["an organization that grants official accreditation"]}', NULL, 'apply to an accreditation body / recognized accreditation body', '[{"en":"The school is recognized by a leading international accreditation body.","zh-TW":"這所學校獲得了頂尖的國際認證機構的認可。"},{"en":"Accreditation bodies set standards for educational quality.","zh-TW":"認證機構為教育品質設定標準。"}]', NULL, NULL, 5, 70, NULL),
(71, 'accredited institution', '/''əˌkredɪtɪd ˌɪnstɪˈtjuːʃən/', 'noun', '{"zh-TW":["認可機構；獲認證的院校"],"en":["an educational institution that has been officially recognized as meeting required standards"]}', NULL, 'graduate from an accredited institution / recognized accredited institution', '[{"en":"A degree from an accredited institution is recognized by employers worldwide.","zh-TW":"來自認可機構的學位受到全球雇主的認可。"},{"en":"Ensure that your university is an accredited institution before enrolling.","zh-TW":"在入學前確認你的大學是一所認可機構。"}]', NULL, NULL, 5, 71, NULL),
(72, 'accretion', '/əˈkriːʃən/', 'noun', '{"zh-TW":["增長；積累；漸增"],"en":["growth by the gradual accumulation of additional layers or components"]}', NULL, 'natural accretion / accretion of power / accretion of wealth', '[{"en":"The delta was formed by the accretion of sediment over thousands of years.","zh-TW":"三角洲是數千年來沉積物積累而成的。"},{"en":"The company''s growth came through accretion of smaller acquisitions.","zh-TW":"公司的增長來自於一系列小規模收購的積累。"}]', '{"verb":"accrete","adjective":"accretive"}', NULL, 3, 72, NULL),
(73, 'accretive', '/əˈkriːtɪv/', 'adjective', '{"zh-TW":["增值的；累積成長的"],"en":["relating to the growth of a business through incremental additions"]}', NULL, 'accretive acquisition / accretive deal / accretive to earnings', '[{"en":"The acquisition is expected to be accretive to earnings in year two.","zh-TW":"該收購預計在第二年對盈利具有增值效果。"},{"en":"The board approved only accretive investments.","zh-TW":"董事會只批准增值性投資。"}]', '{"noun":"accretion","verb":"accrete"}', NULL, 3, 73, NULL),
(74, 'accrual', '/əˈkruːəl/', 'noun', '{"zh-TW":["應計；累計"],"en":["an accounting method recognizing revenues and expenses when earned or incurred"]}', NULL, 'accrual accounting / accrual basis / accrual method', '[{"en":"The company reports under the accrual basis of accounting.","zh-TW":"公司採用權責發生制報告。"},{"en":"Accruals ensure expenses match the period they relate to.","zh-TW":"應計確保費用與其相關期間匹配。"}]', '{"verb":"accrue","adjective":"accrued"}', NULL, 3, 74, 741),
(75, 'accrual accounting', '/əˈkruːəl əˈkaʊntɪŋ/', 'noun', '{"zh-TW":["應計制會計；權責發生制"],"en":["an accounting method recording revenues and expenses when earned or incurred"]}', NULL, 'use accrual accounting / switch to accrual accounting', '[{"en":"Most listed companies report under the accrual accounting basis.","zh-TW":"大多數上市公司採用應計制會計報告。"},{"en":"Accrual accounting gives a more accurate picture of financial health.","zh-TW":"應計制會計提供了更準確的財務狀況圖像。"}]', '{"alternative":"cash-basis accounting"}', NULL, 5, 75, NULL),
(76, 'accrual basis', '/əˈkruːəl ˈbeɪsɪs/', 'noun', '{"zh-TW":["應計制；權責發生制"],"en":["an accounting method recognizing income and expenses when incurred, not when paid"]}', NULL, 'report on accrual basis / accrual basis accounting', '[{"en":"Most large companies prepare accounts on an accrual basis.","zh-TW":"大多數大型公司採用應計制編制帳目。"},{"en":"On an accrual basis, revenue is recognized when earned, not when received.","zh-TW":"在應計制下，收入在賺得時確認，而非在收到時。"}]', '{"opposite":"cash basis"}', NULL, 5, 76, NULL),
(77, 'accrue', '/əˈkruː/', 'verb', '{"zh-TW":["累積；應計"],"en":["to accumulate or be received as a regular gain"]}', NULL, 'accrue interest / accrue benefits / accrue overtime', '[{"en":"Interest accrues daily on the outstanding balance.","zh-TW":"利息每天在未償餘額上累積。"},{"en":"Vacation days accrue at the rate of one day per month.","zh-TW":"假期以每月一天的速度累積。"}]', '{"noun":"accrual","adjective":"accrued"}', NULL, 2, 77, 727),
(78, 'accrued expense', '/əˈkruːd ɪkˈspens/', 'noun', '{"zh-TW":["應計費用"],"en":["an expense that has been incurred but not yet paid"]}', NULL, 'record accrued expenses / accrue expenses / accrued expense account', '[{"en":"Wages earned but unpaid at month-end are accrued expenses.","zh-TW":"月末已賺取但未支付的工資是應計費用。"},{"en":"The accountant reviewed all accrued expenses before closing.","zh-TW":"會計師在結帳前審查了所有應計費用。"}]', '{"plural":"accrued expenses","verb":"accrue"}', NULL, 5, 78, NULL),
(79, 'accrued expenses', '/əˈkruːd ɪkˈspensɪz/', 'noun', '{"zh-TW":["應計費用"],"en":["expenses that have been incurred but not yet paid or recorded in financial statements"]}', NULL, 'record accrued expenses / accrued expenses on balance sheet / reduce accrued expenses', '[{"en":"Accrued expenses such as unpaid wages appear as a current liability on the balance sheet.","zh-TW":"未支付工資等應計費用在資產負債表上顯示為流動負債。"},{"en":"Overstating accrued expenses is a common method of smoothing reported earnings.","zh-TW":"高估應計費用是平滑已報告收益的常用方法。"}]', NULL, NULL, 5, 79, NULL),
(80, 'accrued interest', '/əˈkruːd ˈɪntrəst/', 'noun', '{"zh-TW":["應計利息"],"en":["interest that has accumulated since the last payment date"]}', NULL, 'calculate accrued interest / pay accrued interest / accrued interest receivable', '[{"en":"The bond was sold with accrued interest of three months.","zh-TW":"債券以三個月的應計利息出售。"},{"en":"Accrued interest must be recognized on the balance sheet date.","zh-TW":"應計利息必須在資產負債表日確認。"}]', NULL, NULL, 5, 80, NULL),
(81, 'accrued liability', '/əˈkruːd laɪˈæbɪlɪti/', 'noun', '{"zh-TW":["應計負債"],"en":["an expense incurred but not yet paid at the reporting date"]}', NULL, 'record an accrued liability / accrued liability balance', '[{"en":"Salaries payable are recorded as an accrued liability at month end.","zh-TW":"應付薪資在月末被記錄為應計負債。"},{"en":"Accrued liabilities appear in the current liabilities section of the balance sheet.","zh-TW":"應計負債出現在資產負債表的流動負債部分。"}]', NULL, NULL, 5, 81, NULL),
(82, 'acculturation', '/əˌkʌltʃəˈreɪʃən/', 'noun', '{"zh-TW":["文化適應；移植文化"],"en":["the process of cultural change through contact with another culture"]}', NULL, 'acculturation process / acculturation stress / acculturate immigrants', '[{"en":"Acculturation studies examine how migrants adapt to new cultural environments.","zh-TW":"文化適應研究審視移民如何適應新的文化環境。"},{"en":"Acculturation can be a source of identity conflict for first-generation immigrants.","zh-TW":"文化適應對於第一代移民而言可能是身份認同衝突的根源。"}]', '{"verb":"acculturate","adjective":"acculturated"}', NULL, 5, 82, NULL),
(83, 'accumulate', '/əˈkjuːmjəleɪt/', 'verb', '{"zh-TW":["累積；積聚"],"en":["to gather together or acquire an increasing amount"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cumul","meaning":"heap (堆積)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使堆積起來，即「累積」。"}', 'accumulate wealth/debt/experience', '[{"en":"He accumulated considerable wealth over the years.","zh-TW":"他多年來累積了可觀的財富。"},{"en":"Dust had accumulated on the unused equipment.","zh-TW":"未使用的設備上積了灰塵。"}]', '{"noun":"accumulation"}', NULL, 4, 83, 635),
(84, 'accumulated depreciation', '/əˌkjuːmjəleɪtɪd dɪˌpriːʃiˈeɪʃən/', 'noun', '{"zh-TW":["累計折舊"],"en":["the total amount of depreciation charged against an asset since its acquisition"]}', NULL, 'calculate accumulated depreciation / accumulated depreciation account', '[{"en":"Accumulated depreciation is subtracted from cost to show net book value.","zh-TW":"累計折舊從成本中扣除以顯示淨帳面價值。"},{"en":"Fully depreciated assets have accumulated depreciation equal to their cost.","zh-TW":"已完全折舊的資產的累計折舊等於其成本。"}]', NULL, NULL, 5, 84, NULL),
(85, 'accuracy', 'ˈækjərəsi', 'noun', '{"zh-TW":["準確性；精確度","正確性"],"en":["the quality of being correct","freedom from error"]}', NULL, 'data accuracy/improve accuracy', '[{"en":"Please check the accuracy of the figures.","zh-TW":"請核實數字的準確性。"}]', '{"adjective":"accurate","adverb":"accurately"}', NULL, 3, 85, 973),
(86, 'accurate', '/ˈækjərət/', 'adjective', '{"zh-TW":["準確的；精確的","準確的"],"en":["correct in all details; exact","correct in all details"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"cur","meaning":"care (注意)"},"suffix":{"text":"-ate","meaning":"having quality (具有特質)"},"logic":"朝向注意的，即「準確的」。"}', 'accurate information/data/description; accurate information / accurate prediction', '[{"en":"Please ensure that all data entries are accurate.","zh-TW":"請確保所有資料輸入準確無誤。"},{"en":"The forecast proved to be highly accurate.","zh-TW":"該預測被證明非常準確。"},{"en":"The report contains accurate data.","zh-TW":"報告包含準確的數據。"},{"en":"Her prediction turned out to be accurate.","zh-TW":"她的預測結果證明是準確的。"}]', '{"noun":"accuracy","adverb":"accurately"}', NULL, 3, 86, 247),
(87, 'achieve', '/əˈtʃiːv/', 'verb', '{"zh-TW":["達成；實現"],"en":["to successfully reach a goal by effort"]}', '{"prefix":{"text":"a-","meaning":"to (朝向)"},"root":{"text":"chieve","meaning":"come to head (完成)"},"logic":"朝向完成，即「達成」。"}', 'achieve a goal/success/results', '[{"en":"The team achieved record sales this quarter.","zh-TW":"團隊本季度達成了創紀錄的銷售額。"},{"en":"She achieved her ambition of becoming CEO.","zh-TW":"她實現了成為執行長的抱負。"}]', '{"noun":"achievement","adjective":"achievable"}', NULL, 3, 87, 248),
(88, 'achievement', '/əˈtʃiːvmənt/', 'noun', '{"zh-TW":["成就；成績"],"en":["a thing accomplished, especially by effort or skill"]}', NULL, 'academic achievement / achievement award', '[{"en":"She graduated with outstanding academic achievements.","zh-TW":"她以卓越的學業成就畢業。"},{"en":"The award recognizes the student''s remarkable achievements.","zh-TW":"該獎項表彰了學生的卓越成就。"}]', '{"verb":"achieve","adjective":"achievable"}', NULL, 4, 88, 68),
(89, 'acidification', '/əˌsɪdɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["酸化"],"en":["the process of becoming acid; specifically, ocean acidification from CO₂"]}', NULL, 'ocean acidification / soil acidification / acidification of lakes', '[{"en":"Ocean acidification harms marine organisms that build calcium shells.","zh-TW":"海洋酸化損害了構建碳酸鈣外殼的海洋生物。"},{"en":"Industrial emissions have caused acidification of many freshwater lakes.","zh-TW":"工業排放導致許多淡水湖泊酸化。"}]', '{"verb":"acidify","adjective":"acidified"}', NULL, 5, 89, NULL),
(90, 'acknowledge', '/əkˈnɒlɪdʒ/', 'verb', '{"zh-TW":["承認；確認","致謝","承認；答謝"],"en":["to accept or admit the truth of","to show that one has noticed","to accept or admit the truth of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"knowledge","meaning":"knowledge (知識)"},"logic":"朝向知道，即「承認」。"}', 'acknowledge receipt/contribution; acknowledge a mistake / acknowledge receipt', '[{"en":"The company acknowledged the error in the report.","zh-TW":"公司承認了報告中的錯誤。"},{"en":"Please acknowledge receipt of this email.","zh-TW":"請確認收到此電子郵件。"},{"en":"He acknowledged his mistake.","zh-TW":"他承認了自己的錯誤。"}]', '{"noun":"acknowledgment"}', NULL, 4, 90, 249),
(91, 'acknowledgment', '/əkˈnɒlɪdʒmənt/', 'noun', '{"zh-TW":["確認；感謝"],"en":["recognition or confirmation of receiving something"]}', NULL, 'acknowledgment of receipt / written acknowledgment', '[{"en":"Please send an acknowledgment once the package is received.","zh-TW":"收到包裹後請發送確認訊息。"},{"en":"The acknowledgment letter confirmed the application was received.","zh-TW":"確認信確認了申請書已被收到。"}]', '{"verb":"acknowledge","adjective":"acknowledged"}', NULL, 5, 91, NULL),
(92, 'acquire', '/əˈkwaɪər/', 'verb', '{"zh-TW":["獲得；取得","收購","獲得；收購"],"en":["to buy or obtain something","to learn or develop a skill","to gain possession of something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quire","meaning":"seek (尋求)"},"logic":"朝向尋求，即「獲得」。"}', 'acquire skills/knowledge/company; acquire knowledge / acquire a company', '[{"en":"The firm acquired a smaller competitor last year.","zh-TW":"該公司去年收購了一家較小的競爭對手。"},{"en":"She acquired fluency in three languages.","zh-TW":"她掌握了三種語言的流利程度。"},{"en":"She acquired fluency in three languages.","zh-TW":"她習得了三種語言的流利度。"},{"en":"The company acquired a smaller competitor.","zh-TW":"公司收購了一家較小的競爭者。"}]', '{"noun":"acquisition"}', NULL, 3, 92, 2),
(93, 'acquisition', '/ˌækwɪˈzɪʃn/', 'noun', '{"zh-TW":["收購；獲得"],"en":["the purchase of one company by another","the act of obtaining something","the buying of a company","the process of gaining something"]}', '{"prefix":{"text":"ac-","meaning":"toward (朝向)"},"root":{"text":"quis","meaning":"seek (尋求)"},"suffix":{"text":"-ition","meaning":"action (動作)"},"logic":"朝向尋求的動作，即「收購」。"}', 'mergers and acquisitions / acquisition strategy; mergers and acquisitions / customer acquisition', '[{"en":"The acquisition was valued at $2 billion.","zh-TW":"此次收購估值為20億美元。"},{"en":"Customer acquisition costs have increased.","zh-TW":"客戶獲取成本增加了。"},{"en":"The acquisition was worth $2 billion.","zh-TW":"這次收購價值20億美元。"},{"en":"Customer acquisition costs are rising.","zh-TW":"客戶獲取成本正在上升。"}]', '{"verb":"acquire","noun":"acquisition"}', NULL, 4, 93, 491),
(94, 'acquisition cost', '/ˌækwɪˈzɪʃən kɒst/', 'noun', '{"zh-TW":["收購成本；取得成本"],"en":["the total cost to acquire an asset or customer"]}', NULL, 'reduce acquisition cost / customer acquisition cost', '[{"en":"Customer acquisition cost fell after the new referral program launched.","zh-TW":"新推薦計劃推出後，客戶取得成本下降了。"},{"en":"The acquisition cost of the target company included a 20% premium.","zh-TW":"目標公司的收購成本包括20%的溢價。"}]', NULL, NULL, 5, 94, NULL),
(95, 'acronym', '/''ækrənɪm/', 'noun', '{"zh-TW":["首字母縮略詞；縮寫詞"],"en":["a word formed from the initial letters of other words"]}', NULL, 'use an acronym / common acronym / business acronym', '[{"en":"NASA is an acronym for the National Aeronautics and Space Administration.","zh-TW":"NASA是美國國家航空暨太空總署的首字母縮略詞。"},{"en":"Business communication is full of acronyms like ROI and KPI.","zh-TW":"商業溝通中充滿了ROI和KPI等首字母縮略詞。"}]', NULL, NULL, 3, 95, NULL),
(96, 'across', '/əˈkrɒs/', 'preposition', '{"zh-TW":["橫越；在對面","穿過；橫跨","橫越；穿過；在對面"],"en":["from one side to the other","from one side to the other; on the opposite side"]}', NULL, 'come across / across from; across the street / come across; across from (在...對面)', '[{"en":"The office is across from the station.","zh-TW":"辦公室在車站對面。"},{"en":"We expanded across the region.","zh-TW":"我們擴展到整個地區。"},{"en":"She walked across the bridge.","zh-TW":"她走過了那座橋。"},{"en":"I came across an old friend.","zh-TW":"我偶然遇到了一位老朋友。"},{"en":"She walked across the street.","zh-TW":"她走過馬路。"},{"en":"The store is across from the bank.","zh-TW":"商店在銀行對面。"}]', '{"preposition":"across"}', NULL, 2, 96, NULL),
(97, 'act', 'ˈækt', 'verb', '{"zh-TW":["行動；表現","扮演"],"en":["to do something","to perform in a play"]}', NULL, 'act quickly/responsibly', '[{"en":"She acted quickly in the emergency.","zh-TW":"她在緊急情況下迅速行動。"}]', '{"noun":"action, actor","adjective":"active","adverb":"actively"}', NULL, 1, 97, NULL),
(98, 'action', 'ˈækʃən', 'noun', '{"zh-TW":["行動；措施","訴訟"],"en":["the process of doing something","a legal process"]}', NULL, 'take action/course of action', '[{"en":"We need to take immediate action.","zh-TW":"我們需要立即採取行動。"}]', '{"verb":"act","adjective":"active","adverb":"actively"}', NULL, 2, 98, NULL),
(99, 'action item', '/ˈækʃən ˈaɪtəm/', 'noun', '{"zh-TW":["行動事項；待辦事項"],"en":["a specific task assigned to a person following a meeting"]}', NULL, 'assign action items / track action items / close action items', '[{"en":"Each action item was assigned to a specific team member.","zh-TW":"每個行動事項都分配給了特定的團隊成員。"},{"en":"Outstanding action items were reviewed at the start of the meeting.","zh-TW":"未完成的行動事項在會議開始時進行了審查。"}]', '{"plural":"action items"}', NULL, 4, 99, NULL);